/**
 * Keep the phone screen on during practice (iOS Chrome / Safari).
 *
 * Dual strategy:
 * 1. Screen Wake Lock API (iOS 16.4+) — MUST be requested from a user gesture
 * 2. Silent looping video (NoSleep technique) — reliable fallback on iOS WebKit
 *
 * Call keepAwake() inside the Play tap handler, releaseAwake() on Stop.
 */

type WakeLockSentinelLike = {
  released: boolean;
  release: () => Promise<void>;
  addEventListener: (
    type: "release",
    listener: () => void,
    options?: { once?: boolean },
  ) => void;
};

type WakeLockNavigator = Navigator & {
  wakeLock?: {
    request: (type: "screen") => Promise<WakeLockSentinelLike>;
  };
};

/** Silent looping media from NoSleep.js (MIT) */
const SILENT_WEBM = "data:video/webm;base64,";
const SILENT_MP4 = "data:video/mp4;base64,";

let desired = false;
let sentinel: WakeLockSentinelLike | null = null;
let videoEl: HTMLVideoElement | null = null;
let listenersAttached = false;

function nav(): WakeLockNavigator {
  return navigator as WakeLockNavigator;
}

export function isWakeLockSupported(): boolean {
  return typeof navigator !== "undefined" && "wakeLock" in navigator;
}

function isLikelyIOS(): boolean {
  if (typeof navigator === "undefined") return false;
  const ua = navigator.userAgent || "";
  return (
    /iPad|iPhone|iPod/.test(ua) ||
    (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1)
  );
}

function ensureVideo(): HTMLVideoElement {
  if (videoEl) return videoEl;

  const v = document.createElement("video");
  v.setAttribute("playsinline", "");
  v.setAttribute("webkit-playsinline", "");
  v.setAttribute("x5-playsinline", "");
  v.setAttribute("muted", "");
  // Important for iOS autoplay policies
  v.muted = true;
  v.defaultMuted = true;
  v.loop = true;
  v.playsInline = true;
  v.preload = "auto";
  // Prefer mp4 on iOS; webm elsewhere
  if (isLikelyIOS()) {
    v.src = SILENT_MP4;
  } else {
    // webm first, mp4 fallback via source elements
    const s1 = document.createElement("source");
    s1.src = SILENT_WEBM;
    s1.type = "video/webm";
    const s2 = document.createElement("source");
    s2.src = SILENT_MP4;
    s2.type = "video/mp4";
    v.appendChild(s1);
    v.appendChild(s2);
  }
  // Off-screen, nearly invisible — but not display:none (iOS may pause those)
  v.width = 1;
  v.height = 1;
  v.style.cssText =
    "position:fixed;left:-2px;top:-2px;width:1px;height:1px;opacity:0.01;pointer-events:none;z-index:-9999;";
  document.body.appendChild(v);
  videoEl = v;
  return v;
}

async function startVideo(): Promise<boolean> {
  try {
    const v = ensureVideo();
    v.muted = true;
    // Some iOS builds need a currentTime nudge after play
    const p = v.play();
    if (p && typeof (p as Promise<void>).then === "function") {
      await p;
    }
    // If still paused, retry once
    if (v.paused) {
      await v.play();
    }
    return !v.paused;
  } catch {
    return false;
  }
}

function stopVideo(): void {
  if (!videoEl) return;
  try {
    videoEl.pause();
    while (videoEl.firstChild) videoEl.removeChild(videoEl.firstChild);
    videoEl.removeAttribute("src");
    videoEl.load();
    videoEl.remove();
  } catch {
    // ignore
  }
  videoEl = null;
}

async function acquireWakeLock(): Promise<boolean> {
  if (!desired) return false;
  if (typeof document !== "undefined" && document.visibilityState !== "visible") {
    return false;
  }
  if (!isWakeLockSupported()) return false;
  if (sentinel && !sentinel.released) return true;

  try {
    const lock = await nav().wakeLock!.request("screen");
    sentinel = lock;
    lock.addEventListener(
      "release",
      () => {
        if (sentinel === lock) sentinel = null;
        if (desired && document.visibilityState === "visible") {
          void reacquire();
        }
      },
      { once: true },
    );
    return true;
  } catch {
    sentinel = null;
    return false;
  }
}

async function releaseWakeLock(): Promise<void> {
  const current = sentinel;
  sentinel = null;
  if (current && !current.released) {
    try {
      await current.release();
    } catch {
      // ignore
    }
  }
}

async function reacquire(): Promise<void> {
  if (!desired) return;
  await acquireWakeLock();
  // Always keep silent video running on iOS (Wake Lock alone is flaky in Chrome)
  await startVideo();
}

function attachListeners(): void {
  if (listenersAttached) return;
  listenersAttached = true;

  const onVis = () => {
    if (!desired) return;
    if (document.visibilityState === "visible") {
      void reacquire();
    }
  };

  document.addEventListener("visibilitychange", onVis);
  window.addEventListener("pageshow", onVis);
  window.addEventListener("focus", onVis);
}

/**
 * Call from the Play button handler (must be a user gesture on iOS).
 */
export async function keepAwake(): Promise<void> {
  desired = true;
  attachListeners();

  // Start both in the gesture stack — video first (sync-ish), then wake lock
  const videoOk = startVideo();
  const lockOk = acquireWakeLock();
  await Promise.all([videoOk, lockOk]);

  // Belt-and-suspenders: if lock failed or iOS, ensure video is playing
  if (isLikelyIOS() || !sentinel || sentinel.released) {
    await startVideo();
  }
}

/** Call on Stop / timer end / unmount */
export function releaseAwake(): void {
  desired = false;
  void releaseWakeLock();
  stopVideo();
}

/** @deprecated */
export function attachWakeLock(active: boolean): () => void {
  if (active) void keepAwake();
  else releaseAwake();
  return () => {};
}

/** @deprecated */
export function stopWakeLock(): void {
  releaseAwake();
}
